text:
Here's your water tracker with a goal of 8 glasses. Tap a glass or use + and − to count, and it saves for each day on this page.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  body{font-family:Segoe UI,sans-serif;margin:0;padding:24px;text-align:center;background:#f3f8fc;color:#173042}
  h1{font-size:20px;margin:0 0 4px}
  #date{font-size:13px;color:#5a7385;margin-bottom:16px}
  #count{font-size:44px;font-weight:600;margin:8px 0}
  #msg{min-height:20px;font-size:14px;margin-bottom:16px}
  #bar{height:10px;background:#d6e6f2;border-radius:6px;overflow:hidden;max-width:320px;margin:0 auto 20px}
  #fill{height:100%;width:0;background:#2e8fd6;transition:width .3s}
  #glasses{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;max-width:340px;margin:0 auto 20px}
  .g{width:56px;height:72px;border:2px solid #2e8fd6;border-radius:6px 6px 14px 14px;background:#fff;cursor:pointer;padding:0}
  .g.on{background:#2e8fd6}
  .row button{font-size:20px;width:52px;height:44px;border:0;border-radius:10px;background:#2e8fd6;color:#fff;margin:0 6px;cursor:pointer}
  .row button.alt{background:#8aa4b8}
  #reset{margin-top:18px;font-size:13px;background:none;border:0;color:#5a7385;text-decoration:underline;cursor:pointer}
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <div class="row">
    <button class="alt" id="minus" aria-label="Remove a glass">−</button>
    <button id="plus" aria-label="Add a glass">+</button>
  </div>
  <button id="reset">Start today over</button>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0,10);
  var key = "water-" + today;
  var n = 0;
  try { n = parseInt(localStorage.getItem(key) || "0", 10) || 0; } catch (e) {}

  document.getElementById("date").textContent = new Date().toDateString();

  var wrap = document.getElementById("glasses");
  var glasses = [];
  for (var i = 0; i < GOAL; i++) {
    (function (i) {
      var b = document.createElement("button");
      b.className = "g";
      b.setAttribute("aria-label", "Glass " + (i + 1));
      b.onclick = function () { set(n === i + 1 ? i : i + 1); };
      wrap.appendChild(b);
      glasses.push(b);
    })(i);
  }

  function set(v) {
    n = Math.max(0, Math.min(20, v));
    try { localStorage.setItem(key, String(n)); } catch (e) {}
    render();
  }

  function render() {
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    for (var i = 0; i < GOAL; i++) glasses[i].className = "g" + (i < n ? " on" : "");
    var m = n >= GOAL ? "Goal reached. Well done!" :
            n === 0 ? "Start with your first glass." :
            (GOAL - n) + " more to go.";
    document.getElementById("msg").textContent = m;
  }

  document.getElementById("plus").onclick = function () { set(n + 1); };
  document.getElementById("minus").onclick = function () { set(n - 1); };
  document.getElementById("reset").onclick = function () { set(0); };
  render();
</script>
</body>
</html>
```
